import assert from 'node:assert/strict';
import { createFeed } from './src/tenant-event-feed/index.mjs';
import { createRouter } from './src/layered-routing/index.mjs';
import { ExpiringStore } from './src/tenant-cache/store.mjs';
import { TenantCache } from './src/tenant-cache/cache.mjs';

// Feed tenant routing, deep ownership, and atomic rollback.
const feed = createFeed();
const input = { nested: { list: [1] } };
const published = feed.publishBatch('a', [{ type: 'x', payload: input }]);
input.nested.list[0] = 2;
published[0].payload.nested.list[0] = 3;
assert.equal(feed.history('a')[0].payload.nested.list[0], 1);
const seenA = [], seenB = [];
feed.subscribe('a', 0, r => { r.payload.nested.list[0] = 4; seenA.push(r); });
feed.subscribe('b', 0, r => seenB.push(r));
feed.publishBatch('a', [{ type: 'x', payload: { nested: { list: [5] } } }]);
assert.equal(seenA[0].payload.nested.list[0], 4);
assert.equal(feed.history('a')[1].payload.nested.list[0], 5);
assert.equal(seenB.length, 0);
assert.throws(() => feed.publishBatch('a', [
  { type: 'x', payload: { valid: true } },
  { type: 'x', payload: { bad: () => {} } },
]));
assert.deepEqual(feed.history('a').map(r => r.sequence), [1, 2]);
assert.equal(feed.publishBatch('a', [{ type: 'x', payload: {} }])[0].sequence, 3);

// Routing specificity, explicit falsy values, header deletion, tenant cache isolation and cloning.
const defaults = { enabled: true, timeout: 10, label: 'base', headers: { a: 'a', b: 'b' } };
const router = createRouter({ defaults, routes: [
  { id: 'wild', pattern: '*', settings: { target: 'wild' } },
  { id: 'prefix-short', pattern: '/app/*', settings: { target: 'short' } },
  { id: 'prefix-long', pattern: '/app/v1/*', settings: { target: 'long' } },
  { id: 'exact', pattern: '/app/v1/x', settings: { target: 'exact', enabled: false, timeout: 0, label: '' } },
] });
const r1 = router.resolve('t1', '/app/v1/x');
assert.equal(r1.route, 'exact'); assert.equal(r1.enabled, false); assert.equal(r1.timeout, 0); assert.equal(r1.label, '');
r1.headers.a = 'mutated';
assert.equal(router.resolve('t1', '/app/v1/x').headers.a, 'a');
assert.equal(router.resolve('t1', '/app/v1/y').route, 'prefix-long');
assert.equal(router.resolve('t1', '/apple').route, 'wild');
router.setTenant('t1', { enabled: false, headers: { a: null, c: '' } });
assert.deepEqual(router.resolve('t1', '/app/v1/x').headers, { b: 'b', c: '' });
assert.equal(router.resolve('t1', '/app/v1/x').enabled, false);
router.setTenant('t1', { enabled: true });
assert.equal(router.resolve('t1', '/app/v1/x').enabled, false); // matched route still sets false
assert.equal(router.resolve('t2', '/app/v1/x').headers.a, 'a');

// Pair key collision resistance and injected-clock expiration at the exact deadline.
let now = 100;
const store = new ExpiringStore({ now: () => now });
store.set('k', 0, 25);
assert.deepEqual(store.get('k'), { found: true, value: 0 });
now = 125;
assert.deepEqual(store.get('k'), { found: false });
const cache = new TenantCache(new ExpiringStore({ now: () => now }));
let loads = 0;
assert.equal(await cache.getOrLoad('x:y', 'z', async () => { loads++; return false; }), false);
assert.equal(await cache.getOrLoad('x', 'y:z', async () => { loads++; return true; }), true);
assert.equal(loads, 2);
assert.equal(await cache.getOrLoad('x:y', 'z', async () => { loads++; return 1; }), false);
assert.equal(loads, 2);
console.log('additional contract checks passed');
